#define main view44_test_main
#include "test_view44.c"
#undef main
#include "session43.h"
#include "screen44.h"
static void verify(const Model44*m){assert(m->nv>0&&m->nv<256&&m->nf>0);for(int i=0;i<m->nf;i++){Face44 f=m->f[i];assert(f.a<m->nv&&f.b<m->nv&&f.c<m->nv&&f.mat<sizeof(palette44)/sizeof(*palette44));assert(f.a!=f.b&&f.a!=f.c&&f.b!=f.c);Vertex44 a=m->v[f.a],b=m->v[f.b],c=m->v[f.c];int ux=b.x-a.x,uy=b.y-a.y,uz=b.z-a.z,vx=c.x-a.x,vy=c.y-a.y,vz=c.z-a.z;assert(uy*vz-uz*vy||uz*vx-ux*vz||ux*vy-uy*vx);}}
static void frame(Session43*s){draws=0;screen44(&view,s,r,t);assert(!view.dropped);assert(draws<=CAP42+112);if(draws>maxdraw)maxdraw=draws;}
static void save(const char*path){FILE*f=fopen(path,"wb");assert(f);fputs("P6\n320 240\n255\n",f);fwrite(img,1,sizeof img,f);fclose(f);}
int main(int argc,char**argv){const Model44*models[]={&m44_spyro,&m44_crush,&m44_gulp,&m44_ripto,&m44_gnasty,&m44_dragonfly,&m44_tree,&m44_crystal,&m44_portal};int verts=0,faces=0;for(int i=0;i<9;i++){verify(models[i]);verts+=models[i]->nv;faces+=models[i]->nf;}assert(pose44((Vertex44){20,2,0,1},0,0,0,0,16,2).y!=pose44((Vertex44){20,2,0,1},0,0,0,0,16,-2).y);printf("9 meshes: %d vertices, %d faces\n",verts,faces);view44_test_main(0,NULL);Session43 s;init43(&s);int count=0;for(int l=0;l<30;l++){s.route.current_id=l;for(int phase=0;phase<8;phase++){anim44=phase;s.a.face=phase%4;s.a.px=phase&1?20:300;s.a.py=phase&2?44:204;s.a.cd=12;frame(&s);count++;}}s.route.current_kind=WP38_BOSS;for(int b=0;b<5;b++){arena_init41(&s.a,b,0);s.route.current_id=b;for(int phase=0;phase<8;phase++){anim44=phase;s.a.face=phase%4;s.a.px=phase&1?20:300;s.a.py=phase&2?44:204;s.a.bx=phase&1?288:32;s.a.by=phase&2?190:56;s.a.state=A41_ATTACK;s.a.timer=2;s.a.cd=12;for(int i=0;i<6;i++)s.a.shot[i]=(Shot41){32+i*45,60+i*22,0,0,60};frame(&s);count++;}}printf("%d additional asset frames; peak %d triangles across all tests; no overflow\n",count,maxdraw);if(argc==3){init43(&s);s.a.px=138;s.a.py=175;s.a.face=0;paint=1;frame(&s);save(argv[1]);s.route.current_kind=WP38_BOSS;s.route.current_id=4;arena_init41(&s.a,4,0);s.a.px=130;s.a.py=170;s.a.bx=180;s.a.by=90;frame(&s);save(argv[2]);}return 0;}
